function integer append() {
    if ($in.0.scan_at > newest) newest = $in.0.scan_at;
    if ($in.0.scan_at >= $in.0.due_at) overdue = overdue + 2;
    elapsed = elapsed + dateDiff($in.0.origin_at, $in.0.scan_at, day);
    return OK;
}
