    $out.0.asset = $in.0.asset;
    $out.0.latest_scan = newest;
    $out.0.overdue = overdue;
    $out.0.elapsed_days = elapsed;
    return ALL;
}
function void clean() { newest = createDate(1970,1,1,"UTC"); overdue = 0; elapsed = 0L; }
